        # vertical mirror phase fv, horizontal fh inside tile; tiling periods ph,pw >= tile size, period parity odd
        for fv in [False,True]:
            for fh in [False,True]:
                for ph in range(hT2,Ho+1):
                    for pw in range(wT2,Wo+1):
                        pred=np.zeros((Ho,Wo),dtype=int); ok=True
                        def vr(r): q=r%ph; return q if q<hT2 else (2*hT2-1-q)
                        def hr(c): q=c%pw; return q if q<wT2 else (2*wT2-1-q)
                        for i in range(Ho):
                            for j in range(Wo):
                                if T[vr(i),hr(j)]!=O[i,j]: ok=False;break
                            if not ok:break
                        if ok:
                            best.append((name,fv,fh,ph,pw))
    return best
