for n in range(1,9):
    I=np.array(G[f'Demo pair {n} input']); O=np.array(G[f'Demo pair {n} output'])
    vals,cnt=np.unique(I,return_counts=True); bg=int(vals[cnt.argmax()]); lc=int(np.unique(I)[cnt.argsort()[-1]])
    ys,xs=np.where((I!=bg)&(I!=lc)); y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    hT,wT=y1-y0+1,x1-x0+1
    Ho,Wo=O.shape
    # crop pattern P: obj->1, bg->0
    P=((I==lc)&(I!=bg)).astype(int)[y0:y1+1,x0:x1+1]
    HoW,WoW=O.shape
    # mirror sequence over period 2*L with amplitude L-1: s(k)=L-1-abs(((k+p)%2L)- (L-1)) -> value in 0..L-1
    def seq(L,p,H):
        return [L-1-abs(((k+p)%(2*L))-(L-1)) for k in range(H)]
    best=None
    for pv in range(2*hT):
        for phc in range(2*wT):
            R=seq(hT,pv,Ho); C=seq(wT,phc,Wo)
            Q=np.full((Ho,Wo),bg,dtype=int)
            for i in range(Ho):
                for j in range(Wo):
                    src=P[min(R[i],hT-1), min(C[j],wT-1)] if False else P[R[i] if R[i]<hT else 2*hT-R[i], C[j] if C[j]<wT else 2*wT-C[j]]
                    Q[i,j]=lc if src==1 else bg
            m=int((Q!=O).sum())
            if best is None or m<best[0]: best=(m,pv,phc)
    results[n]=(best, (ho:=hT if False else hT, wT if False else wT), O.shape)
    print(f'd{n}: out{O.shape} tile{T_.shape if False else (hT,wT)} best_mism={best[0]} pv={best[1]} pc={best[2]}')
print(results)

import numpy as np, os,re,json,itertools
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
print(sorted(G))
